import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, {m} is a fixed odd integer chosen from {5,7}, and {alpha} and {beta} are fixed positive integers. For a positive integer a and positive real numbers b and c, determine the exact maximum value of\n\n\\[\n\\frac{2^{\\,\\!{m-1}}(\\cos a)^{m} - \\cos(m a)}{{denominator_expr}} \\cdot \\frac{{alpha}\\, a^{2} b + {beta}\\, b^{2} c}{a^{3} + b^{3} + c^{3}}.\n\\]\n\nAfter solving, please output your final answer in the following format:\n### The final answer is: $\\boxed{<your answer>}$\nThe final answer should be given as precisely as possible (using LaTeX symbols such as \\sqrt, \\frac, \\pi, etc.). If the final answer involves a decimal approximation, it must be accurate to at least four decimal places.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose m from {5,7}
m = rng.choice([5, 7])
# Choose distinct positive integers alpha, beta between 2 and 9 to avoid trivial symmetry
nums = list(range(2, 10))
rng.shuffle(nums)
alpha, beta = nums[0], nums[1]
# Build denominator expression so that the trig factor becomes exactly m
if m == 5:
    denominator_expr = "2\\cos a + \\cos(3a)"
else:  # m == 7
    denominator_expr = "(2\\cos a + \\cos(3a))(2\\cos(2a) + 1)"
return {'m': m, 'alpha': alpha, 'beta': beta, 'denominator_expr': denominator_expr}

    def verifier(assign):
# Validate keys
required = ['m', 'alpha', 'beta', 'denominator_expr']
for k in required:
    if k not in assign:
        # Missing slot
        return (False, None)  # missing required slot
m = assign['m']
alpha = assign['alpha']
beta = assign['beta']
denom = assign['denominator_expr']
# Type and domain checks
if not isinstance(m, int) or m not in (5, 7):
    return (False, None)  # invalid m
if not (isinstance(alpha, int) and isinstance(beta, int)):
    return (False, None)  # invalid alpha/beta types
if alpha <= 0 or beta <= 0:
    return (False, None)  # non-positive weights not allowed
if not isinstance(denom, str) or len(denom) == 0:
    return (False, None)  # denominator expression must be a non-empty string
# Trigonometric factor reduces to a constant equal to m by Chebyshev identities:
# For m=5: (16 x^5 - T_5(x)) / (2x + T_3(x)) = 5.
# For m=7: (64 x^7 - T_7(x)) / [(2x + T_3(x))(2(2x^2 - 1) + 1)] = 7.
trig_constant = m
# Optimize the homogeneous degree-3 rational expression via Lagrange multipliers.
# f(a,b,c) = alpha * a^2 b + beta * b^2 c, g(a,b,c) = a^3 + b^3 + c^3.
# At optimum, with g=1, Euler homogeneity implies f* = lambda (the Lagrange multiplier).
import math
s = (beta * math.sqrt(beta) + math.sqrt(beta**3 + 4 * alpha**3)) / (3.0 * math.sqrt(3.0))
lam = s ** (2.0 / 3.0)
total_max = trig_constant * lam
# Build exact LaTeX expression for the answer
# Answer: m * ((beta*sqrt(beta) + sqrt(beta^3 + 4 alpha^3)) / (3 sqrt(3)))^{2/3}
ans_latex = f"{m} \\cdot \left(\\frac{{{beta}\\sqrt{{{beta}}} + \\sqrt{{{beta}^3 + 4\\,{alpha}^3}}}}{{3\\sqrt{{3}}}}\right)^{{2/3}}"
answer = f"### The final answer is: $\\boxed{{{ans_latex}}}$"
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

